// Node 3: Parse Claude Response
const responseText = items[0].json.content[0].text;

// Strip markdown code fences if present
let cleaned = responseText.trim();
if (cleaned.startsWith('```')) {
  cleaned = cleaned.replace(/^```(?:json)?\n?/, '').replace(/\n?```$/, '').trim();
}

// Parse the JSON
let leadData;
try {
  leadData = JSON.parse(cleaned);
} catch (e) {
  // Attempt to extract JSON object from the text
  const match = cleaned.match(/\{[\s\S]*\}/);
  if (match) {
    leadData = JSON.parse(match[0]);
  } else {
    throw new Error('Could not parse Claude response as JSON: ' + cleaned);
  }
}

// Generate job ID from timestamp
const jobId = 'LEAD-' + Date.now().toString().slice(-6);
const today = new Date().toISOString().split('T')[0];

// Enrich with metadata
leadData.id = jobId;
leadData.date_added = today;
leadData.submitted_by = 'email-auto';

// Ensure defaults for required fields
leadData.amount = leadData.amount || 0;
leadData.status = leadData.status || 'lead';
leadData.source = leadData.source || 'email';

return [{ json: leadData }];

// Node 5: Build Draft Invoice from job data
const job = items[0].json;
const today = new Date().toISOString().split('T')[0];

const invoice = {
  id: 'INV-DRAFT-' + job.id,
  job_id: job.id,
  customer: job.customer || '',
  address: job.address || '',
  email: job.email || '',
  phone: job.phone || '',
  scope: job.scope || '',
  job_type: job.job_type || '',
  status: 'draft',
  date_created: today,
  line_items: [],
  subtotal: 0,
  markup_pct: 17.5,
  total: 0,
  notes: 'Auto-created from email lead. Add line items to complete.'
};

return [{ json: invoice }];

